// Parse the email to extract order info
const email = $input.first().json;

const subject = email.subject || '';
const body = email.text || email.snippet || '';
const from = email.from?.value?.[0] || {};

// Extract customer info
const customerEmail = from.address || '';
const customerName = from.name || customerEmail;

// Try to parse items from body
// Expected format (one per line): "BARCODE x QUANTITY" or "PRODUCT_NAME x QUANTITY"
// Example: "3760123456789 x 2" or "T-shirt Bleu XL x 1"
const items = [];
const lines = body.split('\n').filter(l => l.trim());

for (const line of lines) {
  // Match patterns like "something x 2" or "something × 2"
  const match = line.match(/^(.+?)\s*[x×]\s*(\d+)$/i);
  if (match) {
    const nameOrBarcode = match[1].trim();
    const quantity = parseInt(match[2], 10);

    // If looks like a barcode (all digits, 8-13 chars)
    const isBarcode = /^\d{8,13}$/.test(nameOrBarcode);

    items.push({
      barcode: isBarcode ? nameOrBarcode : undefined,
      variantName: isBarcode ? undefined : nameOrBarcode,
      quantity
    });
  }
}

// Fallback: if no items parsed, create a generic item from subject
if (items.length === 0) {
  items.push({
    variantName: subject || 'Article non identifié',
    quantity: 1
  });
}

return [{
  json: {
    customerName,
    customerEmail,
    source: 'gmail',
    notes: `Email: ${subject}`,
    items
  }
}];
